def parse_rows(lines):
    """Parse 'name,qty' lines. Collect every bad line into one ExceptionGroup."""
    errors = []
    totals = {}
    for number, line in enumerate(lines, start=1):
        try:
            name, qty = line.split(",")
            totals[name] = int(qty)
        except ValueError as exc:
            # TODO: attach the context with exc.add_note(f"line {number}: {line!r}")
            # TODO: keep the exception by appending it to errors
            pass
    # TODO: if errors is not empty, raise ExceptionGroup("bad rows", errors)
    return totals

try:
    parse_rows(["a,1", "b,x", "c,2", "d,"])
except ExceptionGroup as eg:
    for e in eg.exceptions:
        print(e, e.__notes__)

practice_challenges.test_code:
assert parse_rows(["a,1", "b,2"]) == {"a": 1, "b": 2}

try:
    parse_rows(["a,1", "b,x", "c,2", "d,"])
    raise AssertionError("bad rows must raise")
except ExceptionGroup as eg:
    assert eg.message == "bad rows"
    assert len(eg.exceptions) == 2
    assert eg.exceptions[0].__notes__ == ["line 2: 'b,x'"]
    assert eg.exceptions[1].__notes__ == ["line 4: 'd,'"]

try:
    parse_rows(["only-one-field"])
    raise AssertionError("a line without a comma must raise")
except ExceptionGroup as eg:
    assert eg.exceptions[0].__notes__ == ["line 1: 'only-one-field'"]
